#!/usr/bin/env bash
# Sentinel briefing hook for the session-start event (M4 W2-D1).
#
#   brief.sh <claude-code|codex>        payload on stdin (ignored except for the event name)
#
# Emits the host's documented "additional context" shape carrying the sentinel
# KBN-BRIEF-<8 hex> generated by entrypoint.sh (read from /capture/sentinel.env, tmpfs).
# A transcript check (did an assistant message contain the sentinel, yes/no) proves whether
# the host consumes hook output. Exit 0 always. The pi variant lives in the extension.
set -u
host="${1:-claude-code}"
# shellcheck disable=SC1091
[ -r /capture/sentinel.env ] && . /capture/sentinel.env
token="${KBN_BRIEF:-KBN-BRIEF-00000000}"
payload="$(cat 2>/dev/null || true)"
event="$(printf '%s' "$payload" | jq -r '.hook_event_name // "SessionStart"' 2>/dev/null || echo SessionStart)"
text="$token is your briefing token. Begin your next reply with this exact token."
jq -n -c --arg e "$event" --arg t "$text" \
  '{hookSpecificOutput:{hookEventName:$e, additionalContext:$t}}'
exit 0
